import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

# Custom CUDA kernel for optimized pointwise convolution
pointwise_conv_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void pointwise_conv_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int B,
    int C_in,
    int H,
    int W,
    int C_out
) {
    const int b = blockIdx.z;
    const int h = blockIdx.y;
    const int w = blockIdx.x;
    const int c_out = threadIdx.x;

    if (c_out >= C_out) return;

    float sum = 0.0f;
    for(int c_in = 0; c_in < C_in; c_in++) {
        const int input_idx = b * C_in * H * W + c_in * H * W + h * W + w;
        sum += input[input_idx] * weight[c_out * C_in + c_in];
    }

    if (bias) sum += bias[c_out];

    const int output_idx = b * C_out * H * W + c_out * H * W + h * W + w;
    output[output_idx] = sum;
}

torch::Tensor pointwise_conv_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias
) {
    int B = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int C_out = weight.size(0);

    auto output = torch::zeros({B, C_out, H, W}, input.options());

    const dim3 blocks(W, H, B);
    const dim3 threads(C_out, 1, 1);

    const float* bias_ptr = bias.defined() ? bias.data_ptr<float>() : nullptr;

    pointwise_conv_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        B,
        C_in,
        H,
        W,
        C_out
    );

    return output;
}
"""

pointwise_conv_cpp = "torch::Tensor pointwise_conv_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"

# Load the custom CUDA kernel
pointwise_conv = load_inline(
    name="pointwise_conv",
    cpp_sources=pointwise_conv_cpp,
    cuda_sources=pointwise_conv_source,
    functions=["pointwise_conv_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[""]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, bias: bool = False):
        super(ModelNew, self).__init__()
        self.out_channels = out_channels
        self.weight = nn.Parameter(torch.Tensor(out_channels, in_channels))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.weight.view(self.out_channels, -1).contiguous()
        bias = self.bias.contiguous() if self.bias is not None else torch.tensor([], device=x.device)
        return pointwise_conv.pointwise_conv_cuda(x, weight, bias)
